CREATE DATABASE IF NOT EXISTS delivery_workbench CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE delivery_workbench;
CREATE TABLE IF NOT EXISTS knowledge (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200) NOT NULL, content TEXT NOT NULL, tags VARCHAR(500) NOT NULL DEFAULT '', date DATE NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_knowledge_date (date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS delivery_tasks (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200) NOT NULL, project VARCHAR(200) NOT NULL, priority ENUM('高','中','低') NOT NULL DEFAULT '中', due DATE NOT NULL, status ENUM('待处理','进行中','已完成') NOT NULL DEFAULT '待处理', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_task_status_due (status, due)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS issues (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, title VARCHAR(300) NOT NULL, project VARCHAR(200) NOT NULL, source VARCHAR(50) NOT NULL, status ENUM('跟进中','待确认','已解决') NOT NULL DEFAULT '跟进中', updated VARCHAR(50) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_issue_status (status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bugs (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, title VARCHAR(300) NOT NULL, project VARCHAR(200) NOT NULL, symptom TEXT NOT NULL, root TEXT NOT NULL, prevention TEXT NOT NULL, date DATE NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_bug_date (date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE USER IF NOT EXISTS 'delivery_app'@'127.0.0.1' IDENTIFIED BY '请替换为高强度密码';
GRANT SELECT, INSERT, UPDATE, DELETE ON delivery_workbench.* TO 'delivery_app'@'127.0.0.1';
FLUSH PRIVILEGES;
